const items = $input.all();
if (!items.length) {
  return [{ json: { is_last: false, rows: [], status_message_id: null } }];
}

const rows = items.map(i => i.json);

// Находим максимальный ID (последнее поступившее фото)
const ids = rows.map(r => Number(r.id)).filter(id => !isNaN(id));
const maxId = Math.max(...ids);

const currentFileId = $('Wait').item.json.file_id;
const currentRow = rows.find(r => String(r.file_id).trim() === String(currentFileId).trim());
const is_last = currentRow ? Number(currentRow.id) === maxId : false;

const sortedRows = [...rows].sort((a, b) => Number(a.id) - Number(b.id));

// Достаем status_message_id из первой строки, где он НЕ пустой
let statusMsgId = null;
for (const r of sortedRows) {
  if (r.status_message_id) {
    const cleanStr = String(r.status_message_id).replace(/['"]+/g, '').trim();
    if (cleanStr !== '' && cleanStr !== 'null' && !isNaN(Number(cleanStr))) {
      statusMsgId = Number(cleanStr);
      break;
    }
  }
}

return [{
  json: {
    is_last,
    rows: sortedRows,
    status_message_id: statusMsgId
  }
}];

const urls = $json.data.map(item => item.secure_url);
const media = urls.map(url => ({ type: "photo", media: url }));

return [{
  json: {
    chat_id: $('Insert row').item.json.chat_id,
    media: media
  }
}];;

const rows = $input.all().map(i => i.json);
if (!rows.length) return [{ json: { is_first: true } }];

const timestamps = rows.map(r => Number(r.timestamp));
const minTimestamp = Math.min(...timestamps);
const currentTimestamp = Number($('Insert row').item.json.timestamp);

return [{ json: { is_first: currentTimestamp === minTimestamp } }];

const publicId = $json.public_id;
const cloudName = "nlwawgpg";

const size = "medium"; // small / medium / large — дефолт при первой отправке
const gravity = "south_east";

const sizeMap = { small: 100, medium: 150, large: 220 };
const width = sizeMap[size];

const url = `https://res.cloudinary.com/${cloudName}/image/upload/l_LOGO,w_${width},g_${gravity},x_10,y_10/${publicId}.jpg`;

return [{
  json: {
    public_id: publicId,
    logo_size: size,
    logo_gravity: gravity,
    preview_url: url
  }
}];

const data = $('Switch').item.json.callback_query.data; // напр. "logosize:medium"
const [action, value] = data.split(':'); // action: logosize/logopos/logoapply, value: medium/south_east/undefined

const session = $input.item.json; // строка из Get Session

return [{
  json: {
    action,       // "logosize" | "logopos" | "logoapply"
    value,        // "medium" | "south_east" | undefined
    row_number: session.id,   // было session.row_number — в Data Table поле называется id
    chat_id: session.chat_id,
    message_id: session.message_id,
    public_id: session.public_id,
    logo_size: action === 'logosize' ? value : session.logo_size,
    logo_gravity: action === 'logopos' ? value : session.logo_gravity
  }
}];

const sizeMap = { small: 100, medium: 150, large: 220 };
const j = $json;
const w = sizeMap[j.logo_size] || 150;

const url = `https://res.cloudinary.com/nlwawgpg/image/upload/l_logo2,w_${w},g_${j.logo_gravity},x_10,y_10/${j.public_id}.jpg`;

return [{ json: { ...j, preview_url: url } }];

